const dictionaries = Object.fromEntries(['hi', 'te'].map((locale, index) => [
  locale,
  Object.fromEntries(entries.map(([source, hindi, telugu]) => [source, index === 0 ? hindi : telugu])),
]));

function translate(source, locale) {
  if (!locale || locale === 'en') return source;
  return dictionaries[locale]?.[source] ?? source;
}

export function useLanguage() {
  const value = useContext(LanguageContext);
  if (!value) throw new Error('useLanguage must be used inside LanguageProvider');
  return value;
}

export function LanguageProvider({ children }) {
  const textRecordsRef = useRef(new WeakMap());
  const attrRecordsRef = useRef(new WeakMap());
  const [language, setLanguage] = useState(() => {
    try {
      const saved = window.localStorage.getItem('medicore-language');
      return ['en', 'hi', 'te'].includes(saved) ? saved : 'en';
    } catch {
      return 'en';
    }
  });

  useEffect(() => {
    document.documentElement.lang = language;
    try { window.localStorage.setItem('medicore-language', language); } catch { /* storage can be disabled */ }

    const textRecords = textRecordsRef.current;
    const attrRecords = attrRecordsRef.current;
    const localizeText = (node) => {
      const current = node.nodeValue;
      if (!current?.trim()) return;
      const saved = textRecords.get(node);
      const source = saved && saved.rendered === current ? saved.source : current;
      const leading = source.match(/^\s*/)?.[0] ?? '';
      const trailing = source.match(/\s*$/)?.[0] ?? '';
      const core = source.trim();
      const result = `${leading}${translate(core, language)}${trailing}`;
      textRecords.set(node, { source, rendered: result });
      if (result !== current) node.nodeValue = result;
    };
    const localizeAttributes = (element) => {
      for (const name of ['placeholder', 'title', 'aria-label', 'alt']) {
        if (!element.hasAttribute?.(name)) continue;
        const current = element.getAttribute(name);
        const records = attrRecords.get(element) ?? {};
        const saved = records[name];
        const source = saved && saved.rendered === current ? saved.source : current;
        const result = translate(source, language);
        records[name] = { source, rendered: result };
        attrRecords.set(element, records);
        if (result !== current) element.setAttribute(name, result);
      }
    };
    const scan = (node) => {
      if (node.nodeType === Node.TEXT_NODE) localizeText(node);
      if (node.nodeType === Node.ELEMENT_NODE) localizeAttributes(node);
      const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
      let child;
      while ((child = walker.nextNode())) {
        if (child.nodeType === Node.TEXT_NODE) localizeText(child);
        else localizeAttributes(child);
      }
    };
    scan(document.body);
    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        if (mutation.type === 'characterData') localizeText(mutation.target);
        for (const added of mutation.addedNodes ?? []) scan(added);
        if (mutation.type === 'attributes') localizeAttributes(mutation.target);
      }
    });
    observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'title', 'aria-label', 'alt'] });
    return () => observer.disconnect();
  }, [language]);

  const value = useMemo(() => ({ language, setLanguage, t: (source) => translate(source, language) }), [language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function LanguageSwitcher() {
  const { language, setLanguage, t } = useLanguage();
  return (
    <label className="flex items-center gap-2 rounded-full border border-white/15 bg-[#09090d]/95 px-3 py-2 text-xs text-white shadow-xl backdrop-blur-md">
      <span aria-hidden="true">🌐</span>
      <span className="sr-only">{t('Language')}</span>
      <select
        aria-label={t('Language')}
        value={language}
        onChange={(event) => setLanguage(event.target.value)}
        className="cursor-pointer bg-transparent text-white outline-none"
      >
        <option className="bg-[#09090d]" value="en">English</option>
        <option className="bg-[#09090d]" value="hi">हिन्दी</option>
        <option className="bg-[#09090d]" value="te">తెలుగు</option>
      </select>
    </label>
  );
}
